package com.jnapanam.sportszone.notification.controller;import com.jnapanam.sportszone.notification.service.NotificationProviderSettingsService;import com.jnapanam.sportszone.notification.provider.*;import com.jnapanam.sportszone.notification.model.*;import com.jnapanam.sportszone.identity.repository.UserRepository;import java.util.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;
@RestController@RequestMapping("/api/v1/admin/notification-providers")@PreAuthorize("hasRole('SUPER_ADMIN')")public class NotificationProviderSettingsController{private final NotificationProviderSettingsService s;private final NotificationProviderRegistry providers;private final UserRepository users;public NotificationProviderSettingsController(NotificationProviderSettingsService s,NotificationProviderRegistry providers,UserRepository users){this.s=s;this.providers=providers;this.users=users;}@GetMapping public Map<String,Object> get(){return s.masked();}@PutMapping public Map<String,Object> put(Authentication a,@RequestBody Map<String,Object>b){s.save(UUID.fromString(a.getName()),b);return s.masked();}@PostMapping("/test/{channel}")public Map<String,Object> test(Authentication a,@PathVariable String channel){UUID id=UUID.fromString(a.getName());var user=users.findById(id).orElseThrow();NotificationChannel ch=NotificationChannel.valueOf(channel.toUpperCase());var n=new Notification(user,ch,"PROVIDER_TEST","Jnapanam provider test","This is a test notification from SuperAdmin provider configuration.");String ref=providers.provider(ch).send(n);return Map.of("success",true,"provider",providers.provider(ch).name(),"reference",ref);}}
